const fs = require('node:fs');
if (!process.env.INTERLOCK_TRIAL_ID || process.cwd() !== fs.realpathSync(process.env.INTERLOCK_TRIAL_WORKSPACE || '.')) throw new Error('Run this example only through a managed local Git comparison');
const file = 'trial-fixture.txt';
if (!fs.lstatSync(file).isFile()) throw new Error('Expected a regular trial fixture');
const before = fs.readFileSync(file, 'utf8');
const after = before + '\nbaseline';
fs.writeFileSync(file, after);
return { before, after, environmentId: process.env.INTERLOCK_TRIAL_ID };
